{
  "tools": [
    {
      "name": "asset_compile",
      "title": "Asset Compile",
      "toolset": "asset",
      "description": "Recompile an asset from its source file. Compile errors and warnings land in the console - check read_console after a failure.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "full": {
            "type": "boolean",
            "description": "Force a full recompile instead of an incremental one.",
            "default": false
          }
        },
        "required": [
          "path"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Success": {
            "type": "boolean"
          },
          "Path": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "Hint": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_info",
      "title": "Asset Info",
      "toolset": "asset",
      "description": "Everything about one asset - name, type, source and compiled file paths, compile state, tags, cloud package, and how many assets it references and is used by. Explore those relationships with asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search. Absolute paths work too."
          }
        },
        "required": [
          "path"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Name": {
            "type": "string"
          },
          "Path": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "Extension": {
            "type": "string"
          },
          "IsGameResource": {
            "type": "boolean"
          },
          "SourceFile": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "IsCompiled": {
            "type": "boolean"
          },
          "IsCompiledAndUpToDate": {
            "type": "boolean"
          },
          "IsCompileFailed": {
            "type": "boolean"
          },
          "CanRecompile": {
            "type": "boolean"
          },
          "IsCloud": {
            "type": "boolean"
          },
          "IsTransient": {
            "type": "boolean"
          },
          "IsProcedural": {
            "type": "boolean"
          },
          "IsTrivialChild": {
            "type": "boolean"
          },
          "Package": {
            "type": "string"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "ReferenceCount": {
            "type": "integer"
          },
          "DependantCount": {
            "type": "integer"
          },
          "LastOpened": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_search",
      "title": "Asset Search",
      "toolset": "asset",
      "description": "Search the asset system by keywords and type. An empty query lists every asset, so use limit and offset to page through. Returns relative asset paths - pass one to asset_info, asset_compile, asset_read or asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Every keyword must match the asset's path or one of its tags. Empty matches everything."
          },
          "type": {
            "type": "string",
            "description": "Filter to one asset type - a file extension (vmdl, vmat, prefab) or friendly name (Model, Material). See asset_types."
          },
          "projectOnly": {
            "type": "boolean",
            "description": "Only assets belonging to the currently open project, excluding engine content and cloud downloads.",
            "default": false
          },
          "unreferencedOnly": {
            "type": "boolean",
            "description": "Only assets nothing else references - useful for finding unused assets. Note map files and code can use an asset without the asset system knowing.",
            "default": false
          },
          "compileFailedOnly": {
            "type": "boolean",
            "description": "Only assets whose last compile failed.",
            "default": false
          },
          "uncompiledOnly": {
            "type": "boolean",
            "description": "Only assets with no compiled version at all.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many assets matched in total, beyond this page."
          },
          "Showing": {
            "type": "integer"
          },
          "Offset": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_write",
      "title": "Asset Write",
      "toolset": "asset",
      "description": "Overwrite a game resource asset's json and recompile it. Read the current json with asset_read first, modify it, and pass the whole document back - this replaces the entire file. Doesn't work on binary assets like models and textures.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "json": {
            "type": "string",
            "description": "The complete json document to write."
          }
        },
        "required": [
          "path",
          "json"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Success": {
            "type": "boolean"
          },
          "Path": {
            "type": "string"
          },
          "Hint": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "compile_status",
      "title": "Compile Status",
      "toolset": "editor",
      "description": "The live state of the project's code compilers - is anything building, did each compiler's last build succeed, and every error and warning with file and line. This is how you check whether a code edit hotloaded cleanly.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsBuilding": {
            "type": "boolean",
            "description": "Whether anything is building right now."
          },
          "Compilers": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string",
                  "description": "The project this compiler builds, like 'base' or 'facepunch.sandbox'."
                },
                "IsBuilding": {
                  "type": "boolean"
                },
                "NeedsBuild": {
                  "type": "boolean"
                },
                "Success": {
                  "type": "boolean",
                  "description": "Whether the last build succeeded. Null when it hasn't built yet."
                },
                "Errors": {
                  "type": "integer"
                },
                "Warnings": {
                  "type": "integer"
                },
                "Diagnostics": {
                  "type": "array",
                  "items": {},
                  "description": "The last build's errors and warnings, errors first, capped at 50."
                }
              },
              "required": []
            },
            "description": "Every compiler, each with its last build's outcome."
          }
        },
        "required": []
      }
    },
    {
      "name": "editor_status",
      "title": "Get Editor Status",
      "toolset": "editor",
      "description": "Get the current state of the editor - engine version, which project is open, the active scene and whether it has unsaved changes, whether play mode is running or paused, how many tools are registered, the directory paths that matter (logs, project code and assets), and the state of the code compiler. Check IsCompiling/LastCompileSucceeded here after editing code instead of relying on read_console - a successful compile can scroll out of view or be mistaken for the last failure you saw.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "EngineVersion": {
            "type": "string"
          },
          "Project": {
            "type": "string"
          },
          "ProjectTitle": {
            "type": "string"
          },
          "ActiveScene": {
            "type": "string"
          },
          "ActiveScenePath": {
            "type": "string"
          },
          "SceneHasUnsavedChanges": {
            "type": "boolean"
          },
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "ToolCount": {
            "type": "integer"
          },
          "IsCompiling": {
            "type": "boolean"
          },
          "LastCompileSucceeded": {
            "type": "boolean"
          },
          "LastCompileErrors": {
            "type": "integer"
          },
          "Paths": {
            "type": "object",
            "properties": {
              "Engine": {
                "type": "string"
              },
              "Logs": {
                "type": "string"
              },
              "ProjectRoot": {
                "type": "string"
              },
              "ProjectSettings": {
                "type": "string"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_build_map",
      "title": "Build Map",
      "toolset": "hammer",
      "description": "Compile the open map, like pressing Build in Hammer's Build Map dialog (which opens to show progress). Saves the map first, since the compile reads what's on disk. Runs in the background - poll hammer_build_status until Building is false, then hammer_compiled_map_stats breaks down what was built. Doesn't launch the map unless loadInEngine is set.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "preset": {
            "type": "string",
            "enum": [
              "Full",
              "Fast",
              "Final",
              "EntitiesOnly",
              "Custom"
            ],
            "description": "Full, Fast (no vis or lighting - quickest), Final (final quality lighting), EntitiesOnly, or Custom for the dialog's current settings.",
            "default": "Fast"
          },
          "loadInEngine": {
            "type": "boolean",
            "description": "Load the map in engine when it's built, if the dialog is set to.",
            "default": false
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_build_status",
      "title": "Build Status",
      "toolset": "hammer",
      "description": "Progress of the map compile hammer_build_map started - whether it's still running, the status line (Done, Failed...), any errors and warnings it printed, and the tail of its log.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "logLines": {
            "type": "integer",
            "description": "How many lines from the end of the log to include.",
            "minimum": 0,
            "maximum": 2000,
            "default": 40
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_compiled_map_stats",
      "title": "Compiled Map Stats",
      "toolset": "hammer",
      "description": "What the compiled map (.vpk) is made of - total size, size by kind (world geometry, lightmaps, physics, vis, entities...), the largest files, and whether it's older than the map's last save. Build with hammer_build_map first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "largest": {
            "type": "integer",
            "description": "How many of the largest files to list.",
            "minimum": 1,
            "maximum": 500,
            "default": 20
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_trace",
      "title": "Trace Ray",
      "toolset": "hammer",
      "description": "Trace a ray through the open map and report the first node it hits, where, and the surface normal - find the floor under a point, check what's in front of the camera, or probe where to place something. Traces Hammer's own geometry, so it works before the map is compiled.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          },
          "meshesOnly": {
            "type": "boolean",
            "description": "Only hit mesh geometry, ignoring entities and game objects.",
            "default": false
          },
          "skipToolsMaterials": {
            "type": "boolean",
            "description": "Don't hit tools materials like clip or trigger.",
            "default": false
          },
          "hitBackfaces": {
            "type": "boolean",
            "description": "Hit faces from behind too. A back face hit (the normal points along the ray) means the ray started inside something.",
            "default": false
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean"
          },
          "Position": {
            "type": "string"
          },
          "Normal": {
            "type": "string"
          },
          "Node": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "integer"
              },
              "Kind": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              },
              "ClassName": {
                "type": "string"
              },
              "Description": {
                "type": "string"
              },
              "Position": {
                "type": "string"
              },
              "Parent": {
                "type": "integer"
              },
              "GameObject": {
                "type": "string"
              },
              "Selected": {
                "type": "boolean"
              },
              "Visible": {
                "type": "boolean"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "read_console",
      "title": "Read Console",
      "toolset": "instance",
      "description": "Read recent console output, oldest first - what the editor and game logged: prints, warnings, errors, exceptions, compile results. This is how you see the effect of what you just did. Errors come with the top of their stack trace. Every read ends with a cursor - pass it back as 'since' next time to get only what was logged after it, instead of re-reading the same output.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "limit": {
            "type": "integer",
            "description": "How many of the most recent matching entries to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "minimumLevel": {
            "type": "string",
            "enum": [
              "Trace",
              "Info",
              "Warn",
              "Error"
            ],
            "description": "Lowest severity to include.",
            "default": "Trace"
          },
          "filter": {
            "type": "string",
            "description": "Only entries whose message or logger name contains this, case insensitive."
          },
          "since": {
            "type": "integer",
            "description": "Cursor from a previous read - only entries logged after it come back. 0 reads the most recent.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    }
  ],
  "total": 128
}
